package com.farmmacro.gui;

import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.resources.Identifier;

/** Monochrome 16x16 interface icons (atlas generated by tools/gen_ui_icons.py), tinted at draw time. */
public final class UiIcons {
    public static final int SEARCH = 0,
            CLOSE = 1,
            BACK = 2,
            CHEVRON_RIGHT = 3,
            CHEVRON_DOWN = 4,
            GEAR = 5,
            HUD = 6,
            SLIDERS = 7,
            PLAY = 8,
            STOP = 9,
            SAVE = 10,
            TRASH = 11,
            PENCIL = 12,
            GRID = 13,
            PLUS = 14,
            FOLDER = 15,
            COPY = 16,
            REFRESH = 17,
            PIN = 18,
            INFO = 19,
            WARN = 20,
            KEYBOARD = 21,
            EYE = 22,
            CHECK = 23,
            PAUSE = 24,
            RECORD = 25,
            UNDO = 26,
            REDO = 27,
            STAR = 28,
            CLOCK = 29,
            DOWNLOAD = 30,
            UPLOAD = 31;

    /** No icon: pass to widgets that take an optional icon. */
    public static final int NONE = -1;

    private static final int CELL = 16, COLUMNS = 8, ROWS = 4, COUNT = COLUMNS * ROWS;
    private static final Identifier ATLAS = Identifier.fromNamespaceAndPath("farmmacro", "textures/gui/icons.png");

    public static void draw(GuiGraphicsExtractor g, int icon, int x, int y, int argbColor) {
        draw(g, icon, x, y, CELL, argbColor);
    }

    public static void draw(GuiGraphicsExtractor g, int icon, int x, int y, int size, int argbColor) {
        if (icon < 0 || icon >= COUNT || size <= 0) return;
        g.blit(
                RenderPipelines.GUI_TEXTURED,
                ATLAS,
                x,
                y,
                (icon % COLUMNS) * CELL,
                (icon / COLUMNS) * CELL,
                size,
                size,
                CELL,
                CELL,
                COLUMNS * CELL,
                ROWS * CELL,
                argbColor);
    }

    private UiIcons() {}
}
